// Deterministic noise (ADR 0001: everything is generated by code and seeded, so the burger
// looks the same on every load). Pure functions: used by the models and by the texture
// recipes, on the page and in the texture workers.

/** Small seeded PRNG (mulberry32). */
export function random(seed) {
  let a = seed >>> 0;
  return () => {
    a = (a + 0x6d2b79f5) >>> 0;
    let t = a;
    t = Math.imul(t ^ (t >>> 15), t | 1);
    t ^= t + Math.imul(t ^ (t >>> 7), t | 61);
    return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
  };
}

const hash = (x, y, z, seed) => {
  let h = Math.imul(x, 374761393) ^ Math.imul(y, 668265263) ^ Math.imul(z, 2147483647) ^ Math.imul(seed, 1274126177);
  h = Math.imul(h ^ (h >>> 13), 1274126177);
  return ((h ^ (h >>> 16)) >>> 0) / 4294967296;
};
const smooth = (t) => t * t * (3 - 2 * t);
const lerp = (a, b, t) => a + (b - a) * t;

/** 3D value noise in [0, 1]. `period` (integer) makes x and y tile, for seamless textures. */
// Inlined, without closures: it runs hundreds of thousands of times while the page loads.
export function noise(x, y, z = 0, seed = 0, period = 0) {
  const xi = Math.floor(x), yi = Math.floor(y), zi = Math.floor(z);
  const xf = smooth(x - xi), yf = smooth(y - yi), zf = smooth(z - zi);
  const x0 = period ? ((xi % period) + period) % period : xi;
  const x1 = period ? (((xi + 1) % period) + period) % period : xi + 1;
  const y0 = period ? ((yi % period) + period) % period : yi;
  const y1 = period ? (((yi + 1) % period) + period) % period : yi + 1;
  return lerp(
    lerp(lerp(hash(x0, y0, zi, seed), hash(x1, y0, zi, seed), xf), lerp(hash(x0, y1, zi, seed), hash(x1, y1, zi, seed), xf), yf),
    lerp(
      lerp(hash(x0, y0, zi + 1, seed), hash(x1, y0, zi + 1, seed), xf),
      lerp(hash(x0, y1, zi + 1, seed), hash(x1, y1, zi + 1, seed), xf),
      yf,
    ),
    zf,
  );
}

/** Fractal noise in roughly [0, 1]: `octaves` layers of value noise, each twice as fine. */
export function fbm(x, y, z = 0, { octaves = 4, seed = 0, period = 0 } = {}) {
  let sum = 0, amplitude = 0.5, total = 0, frequency = 1;
  for (let i = 0; i < octaves; i++) {
    sum += amplitude * noise(x * frequency, y * frequency, z * frequency, seed + i * 17, period * frequency);
    total += amplitude;
    amplitude *= 0.5;
    frequency *= 2;
  }
  return sum / total;
}
